  "Anim_VerticalJumpsHorizontalJumps": {
    returnType: "static void",
    params: "struct Sprite *sprite",
    callsTo: ["Sin"],
    lineCount: 32,
    bodyC: "s32 counter = sprite->data[2];\n\n    if (counter > 768)\n    {\n        sprite->callback = WaitAnimEnd;\n        sprite->x2 = 0;\n        sprite->y2 = 0;\n    }\n    else\n    {\n        s16 divCounter = counter / 128;\n\n        switch (divCounter)\n        {\n        case 0:\n        case 1:\n            sprite->x2 = 0;\n            break;\n        case 2:\n            counter = 0;\n            break;\n        case 3:\n            sprite->x2 = -(counter % 128 * 8) / 128;\n            break;\n        case 4:\n            sprite->x2 = (counter % 128) / 8 - 8;\n            break;\n        case 5:\n            sprite->x2 = -(counter % 128 * 8) / 128 + 8;\n            break;\n        }\n\n        sprite->y2 = -(Sin(counter % 128, 8));\n    }\n\n    sprite->data[2] += 12;",
  },
